using ghidra.app.plugin.core.assembler;
using ghidra.program.model.lang;
using ghidra.trace.model.guest;
using ghidra.trace.model.program;

public class FixedPlatformTraceDisassembleAction : AbstractTraceDisassembleAction {
	private LanguageID altLangID;
	private TracePlatform platform;

	public FixedPlatformTraceDisassembleAction(DebuggerDisassemblerPlugin plugin,
			LanguageID altLangID, TracePlatform platform) {
		this.altLangID = altLangID;
		this.platform = platform;
		super(plugin, "Disassemble Trace as " + altLangID);

		MenuData menuData = new MenuData(new string[] { "Disassemble as", altLangID.toString() });
		menuData.setParentMenuGroup(AbstractPatchAction.MENU_GROUP);
		setPopupMenuData(menuData);
	}

	/* @Override */
	protected TracePlatform getPlatform(TraceProgramView view) {
		return platform;
	}

	/* @Override */
	protected LanguageID getAlternativeLanguageID() {
		return altLangID;
	}
}
